// Превращает строки листа Settings (key/value) в объект и прокидывает дальше.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def) {
  if (v === undefined || v === '') return def;
  return String(v).toLowerCase() === 'true' || v === '1';
}
function num(v, def) {
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
}
const cfg = {
  owner_chat_id: settings.owner_chat_id || '<REDACTED_CHAT_ID>',
  manager_chat_id: settings.manager_chat_id || '',
  allowed_chat_ids: (settings.allowed_chat_ids || settings.owner_chat_id || '<REDACTED_CHAT_ID>'),
  sla_hot_hours: num(settings.sla_hot_hours, 4),
  sla_warm_hours: num(settings.sla_warm_hours, 24),
  sla_repeat_hours: num(settings.sla_repeat_hours, 6),
  default_responsible: settings.default_responsible || 'Геннадий',
  ai_model: settings.ai_model || 'gpt-4.1-mini',
  ai_enabled_for_hot: bool(settings.ai_enabled_for_hot, true),
  ai_enabled_for_warm: bool(settings.ai_enabled_for_warm, true),
  ai_enabled_for_cold: bool(settings.ai_enabled_for_cold, false),
  auto_reply_enabled: bool(settings.auto_reply_enabled, false),
  auto_reply_default_lang: (settings.auto_reply_default_lang || 'ru').toLowerCase(),
  follow_up_enabled: bool(settings.follow_up_enabled, false),
  followup_hot_hours: num(settings.followup_hot_hours, 24),
  followup_warm_hours: num(settings.followup_warm_hours, 72),
  timezone: settings.timezone || 'Europe/Chisinau',
  currency: settings.currency || 'EUR'
};
return [{ json: { settings: cfg } }];

// SLA Select (Premium) — одна запись на лид, под новую схему Pipeline/Settings.
const cfg = $('Settings to Object').first().json.settings || {};
const rows = $input.all().map(i => i.json);
const now = new Date();

function val(r, ...keys){ for(const k of keys){ if(r[k]!==undefined&&r[k]!==null&&String(r[k]).trim()!=='') return String(r[k]).trim(); } return ''; }
function hoursSince(ts){ const d=new Date(ts); return Number.isNaN(d.getTime())?Infinity:(now-d)/36e5; }

const STOP_STAGES = ['won','lost','closed','nurture','incomplete','закрыт'];
const out = [];
for (const r of rows) {
  const priority = val(r,'priority').toUpperCase();
  if (priority !== 'HOT' && priority !== 'WARM') continue;            // только HOT/WARM

  const stage = val(r,'deal_stage').toLowerCase();
  if (STOP_STAGES.some(x => stage.includes(x))) continue;            // не Won/Lost/Nurture/Incomplete

  const sla = val(r,'sla_status').toLowerCase();
  if (sla === 'done' || sla === 'nurture') continue;                 // не Done/Nurture
  if (sla === 'snoozed') {                                           // не Snoozed в будущее
    const until = new Date(val(r,'sla_snooze_until'));
    if (!Number.isNaN(until.getTime()) && until > now) continue;
  }

  const slaHours = priority === 'HOT' ? Number(cfg.sla_hot_hours||4) : Number(cfg.sla_warm_hours||24);
  const follow = val(r,'next_follow_up_at');
  const overdueByFollow = follow ? (new Date(follow) < now) : false;
  const createdAt = val(r,'created_at');
  const overdueByAge = createdAt ? hoursSince(createdAt) >= slaHours : false;
  if (!overdueByFollow && !overdueByAge) continue;                   // просрочка по follow-up или по возрасту

  const repeat = Number(cfg.sla_repeat_hours||6);
  if (hoursSince(val(r,'last_sla_alert_at')) < repeat) continue;     // анти-спам

  const company = val(r,'company')||'—';
  const name = val(r,'name')||'—';
  const zone = val(r,'financial_zone')||'—';
  const contact = [val(r,'phone'), val(r,'telegram'), val(r,'email')].filter(Boolean).join(' · ')||'нет контакта';
  const action = val(r,'next_action')||'связаться с лидом';
  const leadId = val(r,'lead_id');
  if (!leadId) continue;

  const msg =
`SLA НАПОМИНАНИЕ — ${priority}/${zone}
Компания: ${company}
Контакт: ${name} (${contact})
Стадия: ${val(r,'deal_stage')||'New'}
Просрочено: ${overdueByFollow ? 'follow-up' : 'нет ответа > '+slaHours+'ч'}
Следующий шаг: ${action}
Lead ID: ${leadId}`;

  out.push({ json: { lead_id: leadId, company, name, financial_zone: zone, priority, sla_message: msg, sla_alert_at: now.toISOString() } });
}
return out;  // пусто -> Telegram не получит items -> пустые сообщения не отправляются

// Mark SLA: запускается ПОСЛЕ успешного Telegram. Данные берём из SLA Select.
const selected = $('SLA Select').all().map(i => i.json);
const now = new Date().toISOString();
return selected.map(i => ({ json: {
  lead_id: i.lead_id,
  priority: i.priority,
  financial_zone: i.financial_zone,
  company: i.company,
  name: i.name,
  last_sla_alert_at: i.sla_alert_at || now,
  last_activity_at: now
}}));

// SLA Activity — управленческий detail.
return $input.all().map(i => ({ json: {
  activity_id: `${i.json.lead_id}-${Date.now()}-${Math.floor(Math.random()*1000)}`,
  ts: new Date().toISOString(),
  lead_id: i.json.lead_id,
  actor: 'system:sla',
  channel: 'telegram',
  action: 'sla_alert_sent',
  detail: `SLA alert sent: priority=${i.json.priority||'-'}; zone=${i.json.financial_zone||'-'}; company=${i.json.company||'-'}; contact=${i.json.name||'-'}`
}}));

